const pinyin = require("pinyin");

function generateChineseSlug(text) {
  // Convertimos el texto a pinyin sin tonos y lo unimos con guiones
  const phonetic = pinyin(text, {
    style: pinyin.STYLE_NORMAL, // Sin acentos/tonos (xìjù -> xiju)
  });
  
  return phonetic.flat().join("-").toLowerCase();
}

